#include <bits/stdc++.h>
using namespace std;
int countDigits(int n) {
    // Base case: check boundary/zero value
    if (n == 0) return 1;
    int count = 0;
    // Process digits / elements until exhausted
    while (n != 0) {
        count++;
        n /= 10;
    }
    return count;
}
// Driver code to test the solution
int main() {
    int n = 12345;
    cout << countDigits(n);
    return 0;
}

