#include <bits/stdc++.h>
using namespace std;
int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}
// Driver code to test the solution
int main() {
    int a = 12, b = 18;
    cout << gcd(a, b);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
bool isArmstrong(int n) {
    int original = n;
    int digits = log10(n) + 1;
    int sum = 0;
    // Process digits / elements until exhausted
    while (n != 0) {
        int d = n % 10;
        sum += pow(d, digits);
        n /= 10;
    }
    return sum == original;
}
// Driver code to test the solution
int main() {
    int n = 153;
    cout << isArmstrong(n);
    return 0;
}

