void reverseArray(vector<int>& arr, int l, int r) {
    // Termination condition: pointers cross boundary
    if (l >= r) return;
    // Swap elements to restore correct ordering
    swap(arr[l], arr[r]);
    reverseArray(arr, l + 1, r - 1);
}
