#include <bits/stdc++.h>
using namespace std;
void selectionSort(vector<int>& arr) {
    int n = arr.size();
    // Iterate through input elements
    for (int i = 0; i < n - 1; i++) {
        int minIndex = i;
        for (int j = i + 1; j < n; j++) {
            if (arr[j] < arr[minIndex])
            minIndex = j;
        }
        // Swap elements to restore correct ordering
        swap(arr[i], arr[minIndex]);
    }
}
// Driver code to test the solution
int main() {
    vector<int> arr = {64, 25, 12, 22, 11};
    selectionSort(arr);
    for (int x : arr) cout << x << " ";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
void bubbleSort(vector<int>& arr) {
    int n = arr.size();
    // Iterate through input elements
    for (int i = 0; i < n - 1; i++) {
        bool swapped = false;
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                // Swap elements to restore correct ordering
                swap(arr[j], arr[j + 1]);
                swapped = true;
            }
        }
        if (!swapped) break;
    }
}
// Driver code to test the solution
int main() {
    vector<int> arr = {5, 1, 4, 2, 8};
    bubbleSort(arr);
    for (int x : arr) cout << x << " ";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
void insertionSort(vector<int>& arr) {
    int n = arr.size();
    // Iterate through input elements
    for (int i = 1; i < n; i++) {
        int key = arr[i];
        int j = i - 1;
        while (j >= 0 && arr[j] > key) {
            arr[j + 1] = arr[j];
            j--;
        }
        arr[j + 1] = key;
    }
}
// Driver code to test the solution
int main() {
    vector<int> arr = {8, 3, 5, 2};
    insertionSort(arr);
    for (int x : arr) cout << x << " ";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
void merge(vector<int>& arr, int l, int m, int r) {
    int n1 = m - l + 1;
    int n2 = r - m;
    vector<int> left(n1), right(n2);
    // Iterate through input elements
    for (int i = 0; i < n1; i++)
    left[i] = arr[l + i];
    for (int j = 0; j < n2; j++)
    right[j] = arr[m + 1 + j];
    int i = 0, j = 0, k = l;
    while (i < n1 && j < n2) {
        if (left[i] <= right[j])
        arr[k++] = left[i++];
        else
        arr[k++] = right[j++];
    }
    while (i < n1)
    arr[k++] = left[i++];
    while (j < n2)
    arr[k++] = right[j++];
}
void mergeSort(vector<int>& arr, int l, int r) {
    // Termination condition: pointers cross boundary
    if (l >= r) return;
    int m = l + (r - l) / 2;
    mergeSort(arr, l, m);
    mergeSort(arr, m + 1, r);
    merge(arr, l, m, r);
}
// Driver code to test the solution
int main() {
    vector<int> arr = {5, 2, 4, 6, 1, 3};
    mergeSort(arr, 0, arr.size() - 1);
    for (int x : arr) cout << x << " ";
    return 0;
}

