    // Iterate through input elements
    for (int i = 0; i < n1; i++) {
        for (int j = 0; j < n2; j++) {
            // Check condition / edge case
            if (!visited[j] && arr1[i] == arr2[j]) {
                res.push_back(arr1[i]);
                visited[j] = 1; // this arr2[j] consumed
