int longestConsecutive_sort(vector<int>& a) {
    int n = (int)a.size();
    // Base case: check boundary/zero value
    if (n == 0) return 0;
    // Sort elements to facilitate greedy / two-pointer logic
    sort(a.begin(), a.end());
