    // Iterate through input elements
    for (int i = 1; i < n; i++) {
        if (a[i] == a[i-1]) continue; // duplicate → ignore
        if (a[i] == a[i-1] + 1) curr++; // consecutive
        else { longest = max(longest, curr); // break
            curr = 1; }
    }
    longest = max(longest, curr);
    return longest;
}
