    while (low <= high) {
        int mid = (low + high) / 2;
        if (possible(arr, mid, m, k)) {
            ans = mid;
            high = mid - 1; // try earlier day
        } else {
        low = mid + 1; // need more days
    }
}
// Return the computed result
return ans;
}
};

