● Only row-wise sorted → Binary search on rows
● Row-wise + column-wise sorted → Staircase search (best)

#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    // Returns row index of max element in a column
    int maxElement(vector<vector<int>>& mat, int col) {
        int n = mat.size();
        int idx = 0;
        // Iterate through input elements
        for (int i = 1; i < n; i++) {
            if (mat[i][col] > mat[idx][col])
            idx = i;
        }
        return idx;
    }
    vector<int> findPeakGrid(vector<vector<int>>& mat) {
        int n = mat.size();
        int m = mat[0].size();
        int low = 0, high = m - 1;
        // Binary search loop: search valid search space
        while (low <= high) {
            int mid = (low + high) / 2;
            int row = maxElement(mat, mid);
            int left = (mid - 1 >= 0) ? mat[row][mid - 1] : INT_MIN;
            int right = (mid + 1 < m) ? mat[row][mid + 1] : INT_MIN;
            if (mat[row][mid] > left && mat[row][mid] > right) {
                return {row, mid};
            }
            else if (left > mat[row][mid]) {
                high = mid - 1;
            }
            else {
                low = mid + 1;
            }
        }
        return {-1, -1};
    }
};
// Driver code to test the solution
