    vector<vector<int>> mat = {
        {4, 2, 5, 1, 4, 5},
        {2, 9, 3, 2, 3, 2},
        {1, 7, 6, 0, 1, 3},
        {3, 6, 2, 3, 7, 2}
    };
    Solution sol;
    vector<int> ans = sol.findPeakGrid(mat);
    cout << ans[0] << " " << ans[1] << endl;
}

