class Solution {
public:
    string reverseWords(string s) {
        string result = "";
        int i = s.size() - 1;
        while (i >= 0) {
            while (i >= 0 && s[i] == ' ') //space skip
            i--;
            if (i < 0) break;
            int end = i;
            while (i >= 0 && s[i] != ' ')
            i--;
            string word = s.substr(i + 1, end - i);
            if (!result.empty())
            result += " ";
            result += word;
