class Solution {
public:
    int myAtoi(string s) {
        int i = 0, sign = 1;
        long res = 0;
        // 1. Skip leading whitespaces
        while (i < s.size() && s[i] == ' ')
        i++;
        // 2. Check sign
        if (i < s.size() && (s[i] == '+' || s[i] == '-')) {
            if (s[i] == '-') sign = -1;
            i++;
        }
        // 3. Convert digits
        while (i < s.size() && isdigit(s[i])) {
            res = res * 10 + (s[i] - '0');
            // 4. Clamp if overflow
            if (sign * res > INT_MAX)
            return INT_MAX;
            if (sign * res < INT_MIN)
            return INT_MIN;
            i++;
        }
        return sign * res;
    }
};
