#include <bits/stdc++.h>
using namespace std;
class Solution {
private:
    void reversePart(string &s, int l, int r) {
        // Two-pointer loop: converge inward from both ends
        while (l < r) {
            // Swap elements to restore correct ordering
            swap(s[l++], s[r--]);
        }
    }
public:
    string reverseWords(string s) {
        int n = s.size();
        // Reverse entire string
        reversePart(s, 0, n - 1);
        int i = 0, j = 0;
        while (j < n) {
            // Skip spaces
            while (j < n && s[j] == ' ') j++;
            if (j >= n) break;
            int start = i;
            // Copy characters of word
            while (j < n && s[j] != ' ') {
                s[i++] = s[j++];
            }
            //j hamesha i ke barabar ya aage hota hai
            // → overwrite ka risk nahi hota.
            // Reverse current word
            reversePart(s, start, i - 1);
            // Add single space
            s[i++] = ' ';
        }
        // Remove trailing space
        if (i > 0) i--;
        return s.substr(0, i);
    }
};
