class Solution {
public:
    vector<int> computeZArray(const string& s) {
        int n = s.length();
        vector<int> z(n, 0);
        int left = 0, right = 0;
        // Iterate through input elements
        for (int i = 1; i < n; i++) {
            if (i <= right)
            z[i] = min(right - i + 1, z[i - left]);
            while (i + z[i] < n && s[z[i]] == s[i + z[i]])
            z[i]++;
            if (i + z[i] - 1 > right) {
                left = i;
                right = i + z[i] - 1;
            }
        }
        return z;
    }
    vector<int> zFunctionSearch(const string& text, const string& pattern) {
        string combined = pattern + "$" + text;
        vector<int> z = computeZArray(combined);
        vector<int> result;
        for (int i = pattern.length() + 1; i < combined.length(); i++) {
            // Check condition / edge case
            if (z[i] == pattern.length()) {
                result.push_back(i - pattern.length() - 1);
            }
        }
        return result;
    }
};
