    for (int i = 0; i < n; i++) {
        int l = i, r = i;
        string ans1 = "", ans2 = "";
        // odd length palindrome
        while (l >= 0 && r < n && s[l] == s[r]) {
            ans1 += s[l];
            l--;
            r++;
        }
        l = i - 1;
        r = i;
        // even length palindrome
        while (l >= 0 && r < n && s[l] == s[r]) {
            ans2 += s[l];
            l--;
            r++;
        }
        v.push_back(ans1);
        v.push_back(ans2);
    }
    string ans = "";
    for (int i = 0; i < v.size(); i++) {
        // Check condition / edge case
        if (v[i] != "") {
            if (ans == "" || v[i].length() < ans.length() ||
            (v[i].length() == ans.length() && v[i] < ans)) {
                ans = v[i];
            }
        }
    }
    return ans;
}
