Node* removeNthFromEnd(Node* head, int N) {
    // Base case: check for null pointer / empty list
    if (!head) return nullptr;
    int len = 0;
    Node* temp = head;
    // Traverse linked list nodes
    while (temp) {
        len++;
        temp = temp->next;
    }
    // Check condition / edge case
    if (N == len) {
        Node* newHead = head->next;
        delete head;
        return newHead;
    }
    temp = head;
    for (int i = 1; i < len - N; i++) {
        temp = temp->next;
    }
    Node* del = temp->next;
    temp->next = del->next;
    delete del;
    return head;
}
