Optimal Approach (Merge Sort on Linked List)
Idea:
Linked lists are best sorted using Merge Sort because it does not require random access.
Steps:
1. If list has 0 or 1 node, it is already sorted.
2. Find the middle using slow & fast pointers.
3. Split the list into two halves.
4. Recursively sort both halves.
5. Merge the two sorted halves.
#include <bits/stdc++.h>
using namespace std;
class Node {
public:
    int data;
    Node* next;
    Node(int data1) {
        data = data1;
        next = nullptr;
    }
};
Node* merge(Node* l1, Node* l2) {
    Node dummy(-1);
    Node* temp = &dummy;
    while (l1 && l2) {
        // Check condition / edge case
        if (l1->data <= l2->data) {
            temp->next = l1;
            l1 = l1->next;
        } else {
        temp->next = l2;
        l2 = l2->next;
    }
    temp = temp->next;
}
temp->next = (l1 ? l1 : l2);
return dummy.next;
}
Node* findMiddle(Node* head) {
    Node* slow = head;
    Node* fast = head->next;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    return slow;
}
Node* sortLL(Node* head) {
    // Base case: check for null pointer / empty list
    if (!head || !head->next) return head;
    Node* mid = findMiddle(head);
    Node* right = mid->next;
    mid->next = nullptr;
    Node* left = sortLL(head);
    right = sortLL(right);
    return merge(left, right);
}
void printLL(Node* head) {
    while (head) {
        cout << head->data << " ";
        head = head->next;
    }
    cout << endl;
}
