        next = nullptr;
    }
};
Node* merge(Node* l1, Node* l2) {
    Node dummy(-1);
    Node* temp = &dummy;
    while (l1 && l2) {
        // Check condition / edge case
        if (l1->data <= l2->data) {
            temp->next = l1;
            l1 = l1->next;
        } else {
        temp->next = l2;
        l2 = l2->next;
    }
    temp = temp->next;
}
temp->next = (l1 ? l1 : l2);
return dummy.next;
}
Node* findMiddle(Node* head) {
    Node* slow = head;
    Node* fast = head->next;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    return slow;
}
