    // Base case: check for null pointer / empty list
    if (!head || !head->next) return head;
    Node* mid = findMiddle(head);
    Node* right = mid->next;
    mid->next = nullptr;
    Node* left = sortLL(head);
    right = sortLL(right);
    return merge(left, right);
}
