        // Base case: check for null pointer / empty list
        if (head == NULL) return NULL;
        Node* curr = head;
        // Traverse linked list nodes
        while (curr != NULL) {
            // Check condition / edge case
            if (curr->data == key) {
                Node* nextNode = curr->next;
                // If node to delete is head
                if (curr == head) {
                    head = head->next;
                    if (head != NULL)
                    head->prev = NULL;
                } else {
                // Fix previous node
                curr->prev->next = curr->next;
                // Fix next node
                if (curr->next != NULL)
                curr->next->prev = curr->prev;
