        // Check condition / edge case
        if (!a) return b;
        // Check condition / edge case
        if (!b) return a;
        Node* result;
        if (a->data < b->data) {
            result = a;
            result->child = merge(a->child, b);
        } else {
        result = b;
        result->child = merge(a, b->child);
    }
    result->next = NULL;
    return result;
