#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    double myPow(double x, int n) {
        // Base case: check boundary/zero value
        if (n == 0) return 1.0;
        long long exp = n;
        if (exp < 0) {
            x = 1 / x;
            exp = -exp;
        }
        double ans = 1.0;
        for (long long i = 0; i < exp; i++) {
            ans *= x;
        }
        return ans;
    }
};
// Driver code to test the solution
int main() {
    Solution sol;
    cout << sol.myPow(2.0, 10) << endl;
    cout << sol.myPow(2.0, -2) << endl;
    return 0;
}
Complexity
● Time: O(n)
● Space: O(1)
Optimal Approach (Fast Power / Binary Exponentiation)
Idea
Instead of multiplying x repeatedly, reduce the problem size:
● If n is even → xⁿ = (x²)^(n/2)
● If n is odd → xⁿ = x * xⁿ⁻¹
This reduces calculations drastically.
#include <bits/stdc++.h>
using namespace std;
class Solution {
private:
    double power(double x, long long n) {
        // Base case: check boundary/zero value
        if (n == 0) return 1.0;
        double half = power(x, n / 2);
        if (n % 2 == 0)
        return half * half;
        else
        return half * half * x;
    }
public:
    double myPow(double x, int n) {
        long long exp = n;
        if (exp < 0)
        return 1.0 / power(x, -exp);
        return power(x, exp);
    }
};
