// Inserts an element into the stack in descending order
void insert(stack<int>& s, int x) {
    // If stack is empty or correct position found
    if (s.empty() || s.top() <= x) {
        s.push(x);
        return;
    }
    int temp = s.top();
    s.pop();
    insert(s, x);
    s.push(temp);
}
// Sorts the stack using recursion
void sortStack(stack<int>& s) {
    // Base case
    if (s.empty()) return;
    int temp = s.top();
    s.pop();
    sortStack(s);
    insert(s, temp);
}
