    {
        // Check condition / edge case
        if (idx == s.size()) {
            if (!curr.empty())
            ans.push_back(curr);
            return;
        }
        // Exclude current character
        helper(s, idx + 1, curr, ans);
        // Include current character
        curr.push_back(s[idx]);
        helper(s, idx + 1, curr, ans);
        curr.pop_back();
    }
