        if (index == arr.size()) {
            // Base case: check boundary/zero value
            if (target == 0) {
                ans.push_back(ds);
            }
            return;
        }
        // Pick the current element if possible
        if (arr[index] <= target) {
            ds.push_back(arr[index]);
