#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    // Check if the move is valid
    bool isSafe(int x, int y, int n,
    vector<vector<int>>& maze,
    vector<vector<int>>& visited) {
        return (x >= 0 && x < n &&
        y >= 0 && y < n &&
        maze[x][y] == 1 &&
        visited[x][y] == 0);
    }
    // Backtracking function
    void solve(int x, int y, int n,
    vector<vector<int>>& maze,
    vector<vector<int>>& visited,
    string path,
    vector<string>& res) {
        // Destination reached
        if (x == n - 1 && y == n - 1) {
            res.push_back(path);
            return;
        }
        visited[x][y] = 1;
        // Down
        if (isSafe(x + 1, y, n, maze, visited))
        solve(x + 1, y, n, maze, visited, path + "D", res);
        // Left
        if (isSafe(x, y - 1, n, maze, visited))
        solve(x, y - 1, n, maze, visited, path + "L", res);
        // Right
        if (isSafe(x, y + 1, n, maze, visited))
        solve(x, y + 1, n, maze, visited, path + "R", res);
        // Up
        if (isSafe(x - 1, y, n, maze, visited))
        solve(x - 1, y, n, maze, visited, path + "U", res);
        // Backtrack
        visited[x][y] = 0;
    }
    vector<string> findPath(vector<vector<int>>& maze, int n) {
        vector<string> res;
        vector<vector<int>> visited(n, vector<int>(n, 0));
        // Check condition / edge case
        if (maze[0][0] == 1) {
            solve(0, 0, n, maze, visited, "", res);
        }
        // Return the computed result
        return res;
    }
};

#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    bool wordBreak(string s, vector<string>& wordDict) {
        int n = s.length();
        // Store dictionary words in a set for O(1) lookup
        unordered_set<string> dict(wordDict.begin(), wordDict.end());
        // dp[i] = true if s[0..i-1] can be segmented
        vector<bool> dp(n + 1, false);
        // Memoize subproblem result into DP table
        dp[0] = true; // empty string
        // Find maximum length of any word in dictionary
        int maxLen = 0;
        for (string &w : wordDict) {
            maxLen = max(maxLen, (int)w.size());
        }
        // Fill dp array
        for (int i = 1; i <= n; i++) {
            for (int j = max(0, i - maxLen); j < i; j++) {
                if (dp[j] && dict.count(s.substr(j, i - j))) {
                    // Memoize subproblem result into DP table
                    dp[i] = true;
                    break;
                }
            }
        }
        // Return the computed result
        return dp[n];
    }
};

