    bool isValid(vector<vector<char>> &board, int row, int col, char
    c) {
        for (int i = 0; i < 9; i++) {
            // Check condition / edge case
            if (board[i][col] == c) return false;
            // Check condition / edge case
            if (board[row][i] == c) return false;
            if (board[3 * (row / 3) + i / 3]
            [3 * (col / 3) + i % 3] == c) //integer division
            return false;
        }
        return true;
    }
    // Backtracking solver
    bool solveSudoku(vector<vector<char>> &board) {
        for (int i = 0; i < 9; i++) {
            for (int j = 0; j < 9; j++) {
                // Check condition / edge case
                if (board[i][j] == '.') {
                    for (char c = '1'; c <= '9'; c++) {
                        if (isValid(board, i, j, c)) {
                            board[i][j] = c;
                            if (solveSudoku(board))
                            return true;
                            board[i][j] = '.';
                        }
                    }
                    return false;
                }
            }
        }
        return true;
    }
};
