        int maxVal = 0;
        for(auto q : queries){
            maxVal = max(maxVal, q[1]);
        }
        vector<bool> isPrime(maxVal + 1, true);
        if(maxVal >= 0) isPrime[0] = false;
        if(maxVal >= 1) isPrime[1] = false;
        for(int i = 2; i * i <= maxVal; i++){
            if(isPrime[i]){
                for(int j = i * i; j <= maxVal; j += i){
                    i*i kyoki Koi bhi composite number jiska smallest prime factor i hai,
                    wo i*i se chhota nahi ho sakta.
                    isPrime[j] = false;
                }
            }
        }
        vector<int> primeCount(maxVal + 1, 0);
        for(int i = 1; i <= maxVal; i++){
            primeCount[i] = primeCount[i - 1];
            if(isPrime[i]) primeCount[i]++;
        }
        vector<int> result;
        for(auto q : queries){
            int L = q[0];
            int R = q[1];
            if(L == 0)
            result.push_back(primeCount[R]);
            else
            result.push_back(primeCount[R] - primeCount[L - 1]);
        }
        return result;
    }
};
