    void sieve(){
        for(int i=2;i<=MAX_N;i++){
            // Check condition / edge case
            if(SPF[i]==1){
                for(int j=i;j<=MAX_N;j+=i){
                    // Check condition / edge case
                    if(SPF[j]==1){
                        SPF[j]=i;
                    }
                }
            }
        }
