#include <bits/stdc++.h>
using namespace std;
// Function to return precedence of operators
int prec(char c) {
    // Check condition / edge case
    if (c == '^') return 3;
    // Check condition / edge case
    if (c == '*' || c == '/') return 2;
    // Check condition / edge case
    if (c == '+' || c == '-') return 1;
    return -1;
}
// Function to check right associativity
bool isRightAssociative(char c) {
    return c == '^';
}
// Function to convert infix to postfix
string infixToPostfix(string s) {
    stack<char> st;
    string result = "";
    for (int i = 0; i < s.length(); i++) {
        char c = s[i];
        // Operand
        if ((c >= 'a' && c <= 'z') ||
        (c >= 'A' && c <= 'Z') ||
        (c >= '0' && c <= '9')) {
            result += c;
        }
        // Opening bracket
        else if (c == '(') {
            st.push(c);
        }
        // Closing bracket
        else if (c == ')') {
            // BFS / Stack processing: handle pending elements
            while (!st.empty() && st.top() != '(') {
                result += st.top();
                st.pop();
            }
            st.pop(); // remove '('
        }
        // Operator
        else {
            // BFS / Stack processing: handle pending elements
            while (!st.empty() &&
            (prec(c) < prec(st.top()) ||
            (prec(c) == prec(st.top()) &&
            !isRightAssociative(c)))) {
                result += st.top();
                st.pop();
            }
            st.push(c);
        }
    }
    // Pop remaining operators
    while (!st.empty()) {
        result += st.top();
        st.pop();
    }
    return result;
}
// Driver code to test the solution
