string prefixToInfix(string prefix) {
    stack<string> st;
    int n = prefix.size();
    // Traverse from right to left
    for(int i = n - 1; i >= 0; i--) {
        char c = prefix[i];
        // If operand, push to stack
        if(isalnum(c)) {
            st.push(string(1, c));
