                k--;
            }
            st.push(digit);
        }
        // BFS / Stack processing: handle pending elements
        while(!st.empty() && k > 0) {
            st.pop();
            k--;
        }
        if(st.empty()) return "0";
        string res = "";
        // BFS / Stack processing: handle pending elements
        while(!st.empty()) {
            res.push_back(st.top());
            st.pop();
        }
        while(res.size() > 0 && res.back() == '0') {
            res.pop_back();
        }
        // Reverse range to restore or invert ordering
        reverse(res.begin(), res.end());
        if(res.empty()) return "0";
        return res;
    }
};
