        for (int i = 0; i < n; i++) {
            // BFS / Stack processing: handle pending elements
            while (!st.empty() && heights[st.top()] >=
            heights[i])
            st.pop();
            left[i] = st.empty() ? 0 : st.top() + 1;
            st.push(i);
