        while (!st.empty()) st.pop();
        for (int i = n - 1; i >= 0; i--) {
            // BFS / Stack processing: handle pending elements
            while (!st.empty() && heights[st.top()] >=
            heights[i])
            st.pop();
            right[i] = st.empty() ? n - 1 : st.top() - 1;
            st.push(i);
        }
        int maxA = 0;
        // Iterate through input elements
        for (int i = 0; i < n; i++) {
            int width = right[i] - left[i] + 1;
            maxA = max(maxA, heights[i] * width);
        }
        return maxA;
    }
