#include <bits/stdc++.h>
using namespace std;
class LRUCache {
public:
    class Node {
    public:
        int key, value;
        Node *prev, *next;
        Node(int k, int v) {
            key = k;
            value = v;
            prev = next = nullptr;
        }
    };
    int capacity;
    unordered_map<int, Node*> mp;
    Node *head, *tail;
    LRUCache(int cap) {
        capacity = cap;
        head = new Node(-1, -1);
        tail = new Node(-1, -1);
        head->next = tail;
        tail->prev = head;
    }
    void addNode(Node* node) {
        Node* temp = head->next;
        head->next = node;
        node->prev = head;
        node->next = temp;
        temp->prev = node;
    }
    void removeNode(Node* node) {
        Node* p = node->prev;
        Node* n = node->next;
        p->next = n;
        n->prev = p;
    }
    int get(int key) {
        if (mp.find(key) == mp.end())
        return -1;
        Node* node = mp[key];
        removeNode(node);
        addNode(node);
        return node->value;
    }
    void put(int key, int value) {
        // Check condition / edge case
        if (mp.find(key) != mp.end()) {
            Node* node = mp[key];
            mp.erase(key);
            removeNode(node);
        }
        // Check condition / edge case
        if (mp.size() == capacity) {
            Node* lru = tail->prev;
            mp.erase(lru->key);
            removeNode(lru);
        }
        Node* node = new Node(key, value);
        addNode(node);
        mp[key] = node;
    }
};
// Driver code
int main() {
    LRUCache cache(2);
    cache.put(1, 1);
    cache.put(2, 2);
    cout << cache.get(1) << endl; // 1
    cache.put(3, 3);
    cout << cache.get(2) << endl; // -1
    cache.put(4, 4);
    cout << cache.get(1) << endl; // -1
    cout << cache.get(3) << endl; // 3
    cout << cache.get(4) << endl; // 4
    return 0;
}
● Time Complexity
○ get() → O(1)
○ put() → O(1)
● Space Complexity
○ O(capacity)
(HashMap + Doubly Linked List)

#include <bits/stdc++.h>
using namespace std;
struct Node {
    int key, value, cnt;
    Node *prev, *next;
    Node(int k, int v) {
        key = k;
        value = v;
        cnt = 1;
        prev = next = NULL;
    }
};
struct List {
    int size;
    Node *head, *tail;
    List() {
        head = new Node(0,0);
        tail = new Node(0,0);
        head->next = tail;
        tail->prev = head;
        size = 0;
    }
    void addFront(Node* node) {
        Node* temp = head->next;
        node->next = temp;
        node->prev = head;
        head->next = node;
        temp->prev = node;
        size++;
    }
    void removeNode(Node* node) {
        node->prev->next = node->next;
        node->next->prev = node->prev;
        size--;
    }
};
class LFUCache {
    int maxSize, curSize, minFreq;
    unordered_map<int, Node*> keyNode;
    unordered_map<int, List*> freqListMap;
public:
    LFUCache(int capacity) {
        maxSize = capacity;
        curSize = 0;
        minFreq = 0;
    }
    void updateFreq(Node* node) {
        keyNode.erase(node->key);
        freqListMap[node->cnt]->removeNode(node);
        if(node->cnt == minFreq &&
        freqListMap[node->cnt]->size == 0)
        minFreq++;
        node->cnt++;
        if(freqListMap.find(node->cnt) == freqListMap.end())
        freqListMap[node->cnt] = new List();
        freqListMap[node->cnt]->addFront(node);
        keyNode[node->key] = node;
    }
    int get(int key) {
        if(keyNode.find(key) == keyNode.end())
        return -1;
        Node* node = keyNode[key];
        int val = node->value;
        updateFreq(node);
        return val;
    }
    void put(int key, int value) {
        // Base case: check boundary/zero value
        if(maxSize == 0) return;
        // Check condition / edge case
        if(keyNode.find(key) != keyNode.end()) {
            Node* node = keyNode[key];
            node->value = value;
            updateFreq(node);
        } else {
        // Check condition / edge case
        if(curSize == maxSize) {
            List* list = freqListMap[minFreq];
            keyNode.erase(list->tail->prev->key);
            list->removeNode(list->tail->prev);
            curSize--;
        }
        curSize++;
        minFreq = 1;
        Node* node = new Node(key, value);
        if(freqListMap.find(minFreq) ==
        freqListMap.end())
        freqListMap[minFreq] = new List();
        freqListMap[minFreq]->addFront(node);
        keyNode[key] = node;
    }
}
};
// Driver code to test the solution
