    LFUCache cache(2);
    cache.put(1,1);
    cache.put(2,2);
    cout << cache.get(1) << " ";
    cache.put(3,3);
    cout << cache.get(2) << " ";
    cout << cache.get(3) << " ";
    cache.put(4,4);
    cout << cache.get(1) << " ";
    cout << cache.get(3) << " ";
    cout << cache.get(4);
