using namespace std;
class Solution {
public:
    int maxScore(vector<int>& cardPoints, int k) {
        int n = cardPoints.size();
        int maxSum = 0;
        for(int i = 0; i <= k; i++) {
            int currSum = 0;
            // Take i cards from the front
            for(int j = 0; j < i; j++)
            currSum += cardPoints[j];
            // Take (k - i) cards from the back
            for(int j = 0; j < k - i; j++)
            currSum += cardPoints[n - 1 - j];
            maxSum = max(maxSum, currSum);
        }
        return maxSum;
    }
};
