void MaxHeapify(int arr[], int i, int N){
    int left = 2*i + 1;
    int right = 2*i + 2;
    int largest = i;
    if(left < N && arr[left] > arr[largest])
    largest = left;
    if(right < N && arr[right] > arr[largest])
    largest = right;
    // Check condition / edge case
    if(largest != i){
        // Swap elements to restore correct ordering
        swap(arr[i], arr[largest]);
        MaxHeapify(arr, largest, N);
    }
}
