class Solution {
public:
    ListNode* mergeKSortedLists(vector<ListNode*>& lists) {
        vector<int> values;
        for(auto list : lists) {
            while(list != NULL) {
                values.push_back(list->val);
                list = list->next;
            }
        }
        // Sort elements to facilitate greedy / two-pointer logic
        sort(values.begin(), values.end());
        ListNode* dummy = new ListNode(0);
        ListNode* curr = dummy;
        for(int v : values) {
            curr->next = new ListNode(v);
            curr = curr->next;
        }
