#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    int leastInterval(vector<char>& tasks, int n) {
        unordered_map<char,int> freq;
        for(char t : tasks)
        freq[t]++;
        priority_queue<int> maxHeap;
        for(auto it : freq)
        maxHeap.push(it.second);
        int time = 0;
        while(!maxHeap.empty()) {
            vector<int> temp;
            int cycle = n + 1;
            int i = 0;
            while(i < cycle && !maxHeap.empty()) {
                int cnt = maxHeap.top();
                maxHeap.pop();
                cnt--;
                if(cnt > 0)
                temp.push_back(cnt);
                time++;
                i++;
            }
            // Traverse linked list nodes
            for(int x : temp)
            maxHeap.push(x);
            if(maxHeap.empty())
            break;
            time += (cycle - i);
        }
        return time;
    }
};
// Driver code to test the solution
int main() {
    Solution obj;
    vector<char> tasks = {'A','A','A','B','B','B'};
    int n = 2;
    cout << obj.leastInterval(tasks, n);
    return 0;
}

