using namespace std;
class Solution {
public:
    bool isNStraightHand(vector<int>& hand, int groupSize) {
        if (hand.size() % groupSize != 0)
        return false;
        map<int,int> freq;
        for(int card : hand)
        freq[card]++;
        for(auto it = freq.begin(); it != freq.end(); it++) {
            if(it->second == 0) continue;
            int start = it->first;
            int count = it->second;
            for(int i = 0; i < groupSize; i++) {
                if(freq[start + i] < count)
                return false;
                freq[start + i] -= count;
            }
        }
        return true;
    }
};
