    Solution sol;
    vector<int> hand1 = {1,2,3,6,2,3,4,7,8};
    int groupSize1 = 3;
    cout << sol.isNStraightHand(hand1, groupSize1) << endl;
    vector<int> hand2 = {1,2,3,4,5};
    int groupSize2 = 4;
    cout << sol.isNStraightHand(hand2, groupSize2) << endl;
    return 0;
}

