    greater<pair<int,int>>> pq;
    for(auto p : mp) {
        pq.push({p.second, p.first});
        if(pq.size() > k)
        pq.pop();
    }
    vector<int> res(k);
    for(int i = k-1; i >= 0; i--) {
        res[i] = pq.top().second;
        pq.pop();
    }
    return res;
}
