    vector<int> student = {1, 2, 3};
    vector<int> cookie = {1, 1};
    Solution sol;
    cout << sol.findContentChildren(student, cookie);
    return 0;
}
#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    int findContentChildren(vector<int>& student, vector<int>& cookie)
    {
        int n = student.size();
        int m = cookie.size();
        // Sort elements to facilitate greedy / two-pointer logic
        sort(student.begin(), student.end());
        // Sort elements to facilitate greedy / two-pointer logic
        sort(cookie.begin(), cookie.end());
        vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));
        for(int i = n - 1; i >= 0; i--) {
            for(int j = m - 1; j >= 0; j--) {
                int skip = dp[i][j + 1];
                int take = 0;
                if(cookie[j] >= student[i])
                take = 1 + dp[i + 1][j + 1];
                // Memoize subproblem result into DP table
                dp[i][j] = max(skip, take);
            }
        }
        return dp[0][0];
    }
};
