        data = val;
        left = right = NULL;
    }
};
class Solution {
public:
    vector<vector<int>> preInPostTraversal(Node* root) {
        vector<int> pre, in, post;
        if (root == NULL)
        return {};
        stack<pair<Node*, int>> st;
        st.push({root, 1});
        // BFS / Stack processing: handle pending elements
        while (!st.empty()) {
            auto it = st.top();
            st.pop();
            // Check condition / edge case
            if (it.second == 1) {
                pre.push_back(it.first->data);
                it.second = 2;
                st.push(it);
                if (it.first->left)
                st.push({it.first->left, 1});
            }
            else if (it.second == 2) {
                in.push_back(it.first->data);
                it.second = 3;
                st.push(it);
                if (it.first->right)
                st.push({it.first->right, 1});
            }
            else {
                post.push_back(it.first->data);
            }
        }
        return {pre, in, post};
    }
};
