using namespace std;
// Structure for a binary tree node
struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};
class Solution {
public:
    // Helper DFS function
    bool getPath(TreeNode* root, vector<int>& path, int target) {
        // Base case: check for null pointer / empty list
        if (root == NULL) return false;
        // Add current node
        path.push_back(root->val);
        // If target found
        if (root->val == target)
        return true;
        // Search left or right subtree
        if (getPath(root->left, path, target) ||
        getPath(root->right, path, target))
        return true;
        // Backtrack if target not found
        path.pop_back();
        return false;
    }
    // Main function
    vector<int> rootToNodePath(TreeNode* root, int target) {
        vector<int> path;
        getPath(root, path, target);
        return path;
    }
};
