#include <bits/stdc++.h>
using namespace std;
class TreeNode {
public:
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) {
        val = x;
        left = nullptr;
        right = nullptr;
    }
};
class Solution {
public:
    int widthOfBinaryTree(TreeNode* root) {
        // Base case: check for null pointer / empty list
        if (!root) return 0;
        int maxWidth = 0;
        queue<pair<TreeNode*, int>> q;
        q.push({root, 0});
        // BFS / Stack processing: handle pending elements
        while (!q.empty()) {
            int size = q.size();
            int minIndex = q.front().second;
            int first = 0, last = 0;
            for (int i = 0; i < size; i++) {
                TreeNode* node = q.front().first;
                int currIndex = q.front().second - minIndex;
                q.pop();
                if (i == 0) first = currIndex;
                if (i == size - 1) last = currIndex;
                if (node->left)
                q.push({node->left, 2 * currIndex + 1});
                if (node->right)
                q.push({node->right, 2 * currIndex + 2});
            }
            maxWidth = max(maxWidth, last - first + 1);
        }
        return maxWidth;
    }
};
// Driver code to test the solution
