#include <bits/stdc++.h>
using namespace std;
struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
class Solution {
public:
    vector<int> distanceK(TreeNode* root, TreeNode* target, int k) {
        // Base case: check for null pointer / empty list
        if (!root) return {};
        unordered_map<TreeNode*, TreeNode*> parentMap;
        buildParent(root, parentMap);
        queue<TreeNode*> q;
        unordered_set<TreeNode*> visited;
        q.push(target);
        visited.insert(target);
        int level = 0;
        // BFS / Stack processing: handle pending elements
        while (!q.empty()) {
            int size = q.size();
            if (level == k) break;
            level++;
            for (int i = 0; i < size; i++) {
                TreeNode* node = q.front();
                q.pop();
                // Check condition / edge case
                if (node->left && !visited.count(node->left)) {
                    visited.insert(node->left);
                    q.push(node->left);
                }
                // Check condition / edge case
                if (node->right && !visited.count(node->right)) {
                    visited.insert(node->right);
                    q.push(node->right);
                }
                if (parentMap.count(node) &&
                !visited.count(parentMap[node])) {
                    visited.insert(parentMap[node]);
                    q.push(parentMap[node]);
                }
            }
        }
        vector<int> ans;
        // BFS / Stack processing: handle pending elements
        while (!q.empty()) {
            ans.push_back(q.front()->val);
            q.pop();
        }
        return ans;
    }
private:
    void buildParent(TreeNode* root, unordered_map<TreeNode*,
    TreeNode*>& parentMap) {
        queue<TreeNode*> q;
        q.push(root);
        // BFS / Stack processing: handle pending elements
        while (!q.empty()) {
            TreeNode* node = q.front();
            q.pop();
            if (node->left) {
                parentMap[node->left] = node;
                q.push(node->left);
            }
            if (node->right) {
                parentMap[node->right] = node;
                q.push(node->right);
            }
        }
    }
};
// Driver code to test the solution
