using namespace std;
struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
class Solution {
public:
    int minTime(TreeNode* root, int target) {
        unordered_map<int, vector<int>> graph;
        buildGraph(root, NULL, graph);
        queue<int> q;
        unordered_set<int> visited;
        q.push(target);
        visited.insert(target);
        int time = 0;
        // BFS / Stack processing: handle pending elements
        while (!q.empty()) {
            int size = q.size();
            bool spread = false;
            for (int i = 0; i < size; i++) {
                int node = q.front();
                q.pop();
                for (int nbr : graph[node]) {
                    // Check condition / edge case
                    if (!visited.count(nbr)) {
                        visited.insert(nbr);
                        q.push(nbr);
                        spread = true;
                    }
                }
            }
            if (spread) time++;
        }
        return time;
    }
private:
    void buildGraph(TreeNode* node, TreeNode* parent,
    unordered_map<int, vector<int>>& graph) {
        // Check condition / edge case
        if (!node) return;
        if (parent) {
            graph[node->val].push_back(parent->val);
            graph[parent->val].push_back(node->val);
        }
        buildGraph(node->left, node, graph);
        buildGraph(node->right, node, graph);
    }
};
