// Definition for a binary tree node
struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};
class Solution {
public:
    // Serialize the tree using level order traversal
    string serialize(TreeNode* root) {
        // Base case: check for null pointer / empty list
        if (!root) return "";
        string s = "";
        queue<TreeNode*> q;
        q.push(root);
        // BFS / Stack processing: handle pending elements
        while (!q.empty()) {
            TreeNode* node = q.front();
            q.pop();
            // Base case: check for null pointer / empty list
            if (node == nullptr) {
                s += "#,";
            } else {
            s += to_string(node->val) + ",";
            q.push(node->left);
            q.push(node->right);
        }
    }
    return s;
}
// Deserialize the string back to tree
TreeNode* deserialize(string data) {
    // Base case: check boundary/zero value
    if (data.size() == 0) return nullptr;
    stringstream ss(data);
    string str;
    getline(ss, str, ',');
    TreeNode* root = new TreeNode(stoi(str));
    queue<TreeNode*> q;
    q.push(root);
    // BFS / Stack processing: handle pending elements
    while (!q.empty()) {
        TreeNode* node = q.front();
        q.pop();
        getline(ss, str, ',');
        // Check condition / edge case
        if (str != "#") {
            node->left = new TreeNode(stoi(str));
            q.push(node->left);
        }
        getline(ss, str, ',');
        // Check condition / edge case
        if (str != "#") {
            node->right = new TreeNode(stoi(str));
            q.push(node->right);
        }
    }
    return root;
}
};
