                while(!q.empty()) {
                    int node = q.front();
                    q.pop();
                    for(auto nbr : adj[node]) {
                        // Check condition / edge case
                        if(!visited[nbr]) {
                            visited[nbr] = 1;
                            q.push(nbr);
                        }
                    }
                }
            }
        }
        return components;
    }
};
