#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    vector<vector<string>> findSequences(string beginWord, string
    endWord,
    vector<string>& wordList) {
        unordered_set<string> st(wordList.begin(), wordList.end());
        queue<vector<string>> q;
        q.push({beginWord});
        vector<string> usedOnLevel;
        usedOnLevel.push_back(beginWord);
        int level = 0;
        vector<vector<string>> ans;
        // BFS / Stack processing: handle pending elements
        while(!q.empty()) {
            vector<string> vec = q.front();
            q.pop();
            if(vec.size() > level) {
                level++;
                for(auto it : usedOnLevel)
                st.erase(it);
                usedOnLevel.clear();
            }
            string word = vec.back();
            // Check condition / edge case
            if(word == endWord) {
                if(ans.size() == 0)
                ans.push_back(vec);
                else if(ans[0].size() == vec.size())
                ans.push_back(vec);
            }
            for(int i = 0; i < word.size(); i++) {
                char original = word[i];
                for(char c = 'a'; c <= 'z'; c++) {
                    word[i] = c;
                    if(st.count(word)) {
                        vec.push_back(word);
                        q.push(vec);
                        usedOnLevel.push_back(word);
                        vec.pop_back();
                    }
                }
                word[i] = original;
            }
        }
        return ans;
    }
};
bool comp(vector<string> a, vector<string> b) {
    string x = "", y = "";
    for(string i : a) x += i;
    for(string i : b) y += i;
    return x < y;
}
