        vector<int> indegree(V, 0);
        // Calculate indegree of each vertex
        for(int i = 0; i < V; i++) {
            for(auto it : adj[i]) {
                indegree[it]++;
            }
        }
        queue<int> q;
        // Push all vertices with indegree 0
        for(int i = 0; i < V; i++) {
            if(indegree[i] == 0)
            q.push(i);
