#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    vector<int> shortestPath(vector<vector<int>>& edges, int N, int M,
    int src) {
        // Adjacency list
        vector<int> adj[N];
        for (auto it : edges) {
            adj[it[0]].push_back(it[1]);
            adj[it[1]].push_back(it[0]);
        }
        // Distance array
        vector<int> dist(N, 1e9);
        dist[src] = 0;
        // BFS queue
        queue<int> q;
        q.push(src);
        // BFS / Stack processing: handle pending elements
        while (!q.empty()) {
            int node = q.front();
            q.pop();
            for (auto it : adj[node]) {
                if (dist[node] + 1 < dist[it]) {
                    dist[it] = dist[node] + 1;
                    q.push(it);
                }
            }
        }
        // Convert unreachable nodes to -1
        for (int i = 0; i < N; i++) {
            if (dist[i] == 1e9)
            dist[i] = -1;
        }
        return dist;
    }
