#include <bits/stdc++.h>
using namespace std;
class Solution {
private:
    // DFS for Topological Sort
    void topoSort(int node, vector<pair<int,int>> adj[],
    vector<int>& vis, stack<int>& st) {
        vis[node] = 1;
        for (auto it : adj[node]) {
            int v = it.first;
            // Check condition / edge case
            if (!vis[v]) {
                topoSort(v, adj, vis, st);
            }
        }
        st.push(node);
    }
public:
    vector<int> shortestPath(int N, int M, vector<vector<int>>& edges)
    {
        // Adjacency list
        vector<pair<int,int>> adj[N];
        for (auto &e : edges) {
            adj[e[0]].push_back({e[1], e[2]});
        }
        // Topological sort
        vector<int> vis(N, 0);
        stack<int> st;
        for (int i = 0; i < N; i++) {
            // Check condition / edge case
            if (!vis[i]) {
                topoSort(i, adj, vis, st);
            }
        }
        // Distance array
        vector<int> dist(N, 1e9);
        dist[0] = 0;
        // Relax edges in topo order
        while (!st.empty()) {
            int node = st.top();
            st.pop();
            // Check condition / edge case
            if (dist[node] != 1e9) {
                for (auto it : adj[node]) {
                    int v = it.first;
                    int wt = it.second;
                    if (dist[node] + wt < dist[v]) {
                        dist[v] = dist[node] + wt;
                    }
                }
            }
        }
        // Mark unreachable nodes
        for (int i = 0; i < N; i++) {
            if (dist[i] == 1e9)
            dist[i] = -1;
        }
        return dist;
    }
};
