#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    vector<int> dijkstra(int V, vector<vector<int>> adj[], int S) {
        // Set stores {distance, node}
        set<pair<int,int>> st;
        // Distance array
        vector<int> dist(V, 1e9);
        // Source initialization
        dist[S] = 0;
        st.insert({0, S});
        // BFS / Stack processing: handle pending elements
        while (!st.empty()) {
            auto it = *st.begin();
            st.erase(it);
            int node = it.second;
            int currDist = it.first;
            // Traverse neighbors
            for (auto nbr : adj[node]) {
                int adjNode = nbr[0];
                int wt = nbr[1];
                if (currDist + wt < dist[adjNode]) {
                    // Remove old entry if exists
                    if (dist[adjNode] != 1e9)
                    st.erase({dist[adjNode], adjNode});
                    // Update distance
                    dist[adjNode] = currDist + wt;
                    st.insert({dist[adjNode], adjNode});
                }
            }
        }
        return dist;
    }
};
