        dist[src] = 0;
        pq.push({0, src});
        while (!pq.empty()) {
            auto top = pq.top();
            pq.pop();
            int node = top.second;
            int currDist = top.first;
            // Skip outdated entry
            if (currDist > dist[node]) continue;
            // Relax neighbors
            for (auto it : adj[node]) {
                int next = it.first;
                int wt = it.second;
                if (dist[node] + wt < dist[next]) {
                    dist[next] = dist[node] + wt;
                    pq.push({dist[next], next});
                }
            }
        }
        return dist;
    }
};
