    int n=4, src=0, dst=3, K=1;
    vector<vector<int>>
    flights={{0,1,100},{1,2,100},{2,0,100},{1,3,600},{2,3,200}};
    Solution obj;
    cout<<obj.CheapestFLight(n,flights,src,dst,K);
    return 0;
}

