        queue<pair<int,int>> q;
        q.push({start,0});
        vector<int> dist(100000,1e9);
        dist[start]=0;
        int mod=100000;
        // BFS / Stack processing: handle pending elements
        while(!q.empty()){
            int node=q.front().first;
            int steps=q.front().second;
            q.pop();
