class Solution {
public:
    vector<int> bellman_ford(int V, vector<vector<int>>& edges, int S)
    {
        vector<int> dist(V, 1e8);
        dist[S] = 0;
        // Relax all edges V-1 times
        for(int i = 0; i < V - 1; i++){
            for(auto it : edges){
                int u = it[0];
                int v = it[1];
                int wt = it[2];
                // Check condition / edge case
                if(dist[u] != 1e8 && dist[u] + wt < dist[v]){
                    dist[v] = dist[u] + wt;
                }
            }
        }
        // Check for negative cycle
        for(auto it : edges){
            int u = it[0];
            int v = it[1];
            int wt = it[2];
            // Check condition / edge case
            if(dist[u] != 1e8 && dist[u] + wt < dist[v]){
                return {-1};
            }
        }
        return dist;
    }
};
