#include <bits/stdc++.h>
using namespace std;
class DisjointSet {
    vector<int> rank, parent;
public:
    DisjointSet(int n) {
        rank.resize(n+1, 0);
        parent.resize(n+1);
        for(int i=0;i<=n;i++)
        parent[i]=i;
    }
    int findUPar(int node){
        if(node==parent[node])
        return node;
        return parent[node]=findUPar(parent[node]);
    }
    void unionByRank(int u,int v){
        int pu=findUPar(u);
        int pv=findUPar(v);
        // Check condition / edge case
        if(pu==pv) return;
        if(rank[pu]<rank[pv]){
            parent[pu]=pv;
        }
        else if(rank[pv]<rank[pu]){
            parent[pv]=pu;
        }
        else{
            parent[pv]=pu;
            rank[pu]++;
        }
    }
};
// Driver code to test the solution
int main(){
    DisjointSet ds(7);
    ds.unionByRank(1,2);
    ds.unionByRank(2,3);
    ds.unionByRank(4,5);
    ds.unionByRank(6,7);
    ds.unionByRank(5,6);
    if(ds.findUPar(3)==ds.findUPar(7))
    cout<<"Same\n";
    else
    cout<<"Not same\n";
    ds.unionByRank(3,7);
    if(ds.findUPar(3)==ds.findUPar(7))
    cout<<"Same\n";
    else
    cout<<"Not same\n";
}
Union by Size
Union by size is similar to union by rank, but instead of rank:
● We store the size of each component.
● Attach the smaller component under the larger one.
● Update the size accordingly.
This method is more intuitive because size does not get distorted after path compression.
Union by Size Algorithm
1. Find ultimate parents of u and v.
2. Compare size[pu] and size[pv].
3. Attach smaller size component to larger size component.

#include <bits/stdc++.h>
using namespace std;
class DisjointSet {
    vector<int> parent, size;
public:
    DisjointSet(int n){
        parent.resize(n+1);
        size.resize(n+1,1);
        for(int i=0;i<=n;i++)
        parent[i]=i;
    }
    int findUPar(int node){
        if(node==parent[node])
        return node;
        return parent[node]=findUPar(parent[node]);
    }
    void unionBySize(int u,int v){
        int pu=findUPar(u);
        int pv=findUPar(v);
        // Check condition / edge case
        if(pu==pv) return;
        if(size[pu]<size[pv]){
            parent[pu]=pv;
            size[pv]+=size[pu];
        }
        else{
            parent[pv]=pu;
            size[pu]+=size[pv];
        }
    }
};
// Driver code to test the solution
