        return r>=0 && r<n && c>=0 && c<m;
    }
public:
    vector<int> numOfIslands(int n, int m, vector<vector<int>>&
    operators) {
        DisjointSet ds(n*m);
        vector<vector<int>> vis(n,vector<int>(m,0));
        vector<int> ans;
        int cnt=0;
        int dr[]={-1,0,1,0};
        int dc[]={0,1,0,-1};
        for(auto &op: operators){
            int r=op[0], c=op[1];
            if(vis[r][c]){
                ans.push_back(cnt);
                continue;
            }
            vis[r][c]=1;
            cnt++;
            int node=r*m+c;
            for(int i=0;i<4;i++){
                int nr=r+dr[i];
                int nc=c+dc[i];
                if(isValid(nr,nc,n,m) && vis[nr][nc]){
                    int adjNode=nr*m+nc;
                    // Check condition / edge case
                    if(ds.findUPar(node)!=ds.findUPar(adjNode)){
                        cnt--;
                        ds.unionBySize(node,adjNode);
                    }
                }
            }
            ans.push_back(cnt);
        }
        return ans;
    }
};
