class Solution {
    bool isValid(int r, int c, int n) {
        return r >= 0 && r < n && c >= 0 && c < n;
    }
public:
    int largestIsland(vector<vector<int>>& grid) {
        int n = grid.size();
        DisjointSet ds(n * n);
        int dr[4] = {-1, 0, 1, 0};
        int dc[4] = {0, 1, 0, -1};
        // Step 1: Union existing islands
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < n; j++) {
                if(grid[i][j] == 0) continue;
                for(int d = 0; d < 4; d++) {
                    int ni = i + dr[d];
                    int nj = j + dc[d];
                    // Check condition / edge case
                    if(isValid(ni, nj, n) && grid[ni][nj] == 1) {
                        int node1 = i * n + j;
                        int node2 = ni * n + nj;
                        ds.unionBySize(node1, node2);
                    }
                }
            }
        }
        int ans = 0;
        // Step 2: Try converting each 0 to 1
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < n; j++) {
                if(grid[i][j] == 1) continue;
                set<int> components;
                for(int d = 0; d < 4; d++) {
                    int ni = i + dr[d];
                    int nj = j + dc[d];
                    // Check condition / edge case
                    if(isValid(ni, nj, n) && grid[ni][nj] == 1) {
                        int node = ni * n + nj;
                        components.insert(ds.findUPar(node));
                    }
                }
                int totalSize = 1;
                for(auto comp : components) {
                    totalSize += ds.size[comp];
                }
                ans = max(ans, totalSize);
            }
        }
        // Edge case: all 1s
        for(int i = 0; i < n * n; i++) {
            ans = max(ans, ds.size[ds.findUPar(i)]);
        }
        return ans;
    }
};
