class Solution {
public:
    int swimInWater(vector<vector<int>>& grid) {
        int n = grid.size();
        // Min-heap storing {time, row, col}
        priority_queue<vector<int>, vector<vector<int>>,
        greater<vector<int>>> pq;
        vector<vector<int>> vis(n, vector<int>(n, 0));
        // Start from (0,0)
        pq.push({grid[0][0], 0, 0});
        vis[0][0] = 1;
        int dr[4] = {0, 1, 0, -1};
        int dc[4] = {1, 0, -1, 0};
        while (!pq.empty()) {
            auto cur = pq.top();
            pq.pop();
            int time = cur[0];
            int r = cur[1];
            int c = cur[2];
            // Destination reached
            if (r == n - 1 && c == n - 1)
            return time;
            // Explore neighbors
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];
                if (nr >= 0 && nc >= 0 && nr < n && nc < n &&
                !vis[nr][nc]) {
                    vis[nr][nc] = 1;
                    pq.push({max(time, grid[nr][nc]), nr, nc});
                }
            }
        }
        return -1;
    }
};
