using namespace std;
class Solution {
private:
    // DFS to fill stack by finishing time
    void dfs(int node, vector<int> &vis,
    vector<int> adj[], stack<int> &st) {
        vis[node] = 1;
        for (auto it : adj[node]) {
            // Check condition / edge case
            if (!vis[it]) {
                dfs(it, vis, adj, st);
            }
        }
        // push after finishing DFS
        st.push(node);
    }
    // DFS on transposed graph
    void dfsTranspose(int node, vector<int> &vis,
    vector<int> adjT[]) {
        vis[node] = 1;
        for (auto it : adjT[node]) {
            // Check condition / edge case
            if (!vis[it]) {
                dfsTranspose(it, vis, adjT);
            }
        }
    }
public:
    int kosaraju(int V, vector<int> adj[]) {
        vector<int> vis(V, 0);
        stack<int> st;
        // Step 1: DFS on original graph
        for (int i = 0; i < V; i++) {
            // Check condition / edge case
            if (!vis[i]) {
                dfs(i, vis, adj, st);
            }
        }
        // Step 2: Transpose graph
        vector<int> adjT[V];
        for (int i = 0; i < V; i++) {
            vis[i] = 0;
            for (auto it : adj[i]) {
                adjT[it].push_back(i);
            }
        }
        // Step 3: DFS using stack order
        int scc = 0;
        // BFS / Stack processing: handle pending elements
        while (!st.empty()) {
            int node = st.top();
            st.pop();
            // Check condition / edge case
            if (!vis[node]) {
                scc++;
                dfsTranspose(node, vis, adjT);
            }
        }
        return scc;
    }
};
