// Function to solve the linear house robber problem
long long int solve(vector<int>& arr) {
    int n = arr.size();
    // Check condition / edge case
    if (n == 1) return arr[0];
    long long int prev = arr[0];
    long long int prev2 = 0;
    // Iterate through input elements
    for (int i = 1; i < n; i++) {
        long long int pick = arr[i];
        if (i > 1) pick += prev2;
        long long int nonPick = prev;
        long long int cur_i = max(pick, nonPick);
        prev2 = prev;
        prev = cur_i;
    }
    return prev;
}
// Function to solve the circular house robber problem
long long int robStreet(int n, vector<int> &arr) {
    // Base case: check boundary/zero value
    if (n == 0) return 0;
    // Check condition / edge case
    if (n == 1) return arr[0];
    vector<int> arr1, arr2;
    // Iterate through input elements
    for (int i = 0; i < n; i++) {
        if (i != 0) arr1.push_back(arr[i]);
        if (i != n - 1) arr2.push_back(arr[i]);
    }
    long long int ans1 = solve(arr1);
    long long int ans2 = solve(arr2);
    return max(ans1, ans2);
}
