#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    int countSubsets(vector<int>& arr, int K) {
        vector<int> dp(K + 1, 0);
        // Memoize subproblem result into DP table
        dp[0] = 1;
        if (arr[0] <= K)
        dp[arr[0]]++;
        // Iterate through input elements
        for (int i = 1; i < arr.size(); i++) {
            for (int t = K; t >= arr[i]; t--) {
                // Memoize subproblem result into DP table
                dp[t] += dp[t - arr[i]];
            }
        }
        return dp[K];
