using namespace std;
class Solution {
public:
    int coinChange(vector<int>& coins, int amount) {
        vector<int> dp(amount + 1, -2); // -2 = not computed
        return solve(coins, amount, dp);
    }
private:
    int solve(vector<int>& coins, int rem, vector<int>& dp) {
        // Base case: check boundary/zero value
        if (rem == 0) return 0;
        if (rem < 0) return -1;
        // Check condition / edge case
        if (dp[rem] != -2) return dp[rem];
        int mini = INT_MAX;
        for (int coin : coins) {
            int res = solve(coins, rem - coin, dp);
            if (res >= 0)
            mini = min(mini, 1 + res);
        }
        // Memoize subproblem result into DP table
        dp[rem] = (mini == INT_MAX) ? -1 : mini;
        return dp[rem];
    }
};
Complexity
● Time: O(N × amount)
● Space: O(amount) + recursion stack
