Target Sum (DP - 21)
We are given an array ARR of size N and an integer Target. We must place either a + or - sign
in front of every element of the array. After placing signs in front of all elements, we add them
together. Our task is to count the total number of different ways in which the final sum becomes
exactly equal to Target.
Example 1:
nums = [1,1,1,1,1], target = 3
Possible valid expressions:
-1 + 1 + 1 + 1 + 1 = 3
+1 - 1 + 1 + 1 + 1 = 3
+1 + 1 - 1 + 1 + 1 = 3
+1 + 1 + 1 - 1 + 1 = 3
+1 + 1 + 1 + 1 - 1 = 3
So total ways = 5.
Example 2:
nums = [1], target = 1
Only one way: +1 = 1, so answer = 1.
#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    int findTargetSumWays(vector<int>& nums, int target) {
        int totalSum = accumulate(nums.begin(), nums.end(), 0);
        if ((totalSum - target) < 0 || (totalSum - target) % 2 != 0)
        return 0;
        int subsetSum = (totalSum - target) / 2;
        vector<vector<int>> dp(nums.size(), vector<int>(subsetSum + 1,
        -1));
        return countSubsets(nums, nums.size() - 1, subsetSum, dp);
    }
    int countSubsets(vector<int>& nums, int ind, int target,
    vector<vector<int>>& dp) {
        // Base case: check boundary/zero value
        if (ind == 0) {
            // Base case: check boundary/zero value
            if (target == 0 && nums[0] == 0) return 2;
            // Base case: check boundary/zero value
            if (target == 0 || target == nums[0]) return 1;
            return 0;
        }
        // Check condition / edge case
        if (dp[ind][target] != -1) return dp[ind][target];
        int notPick = countSubsets(nums, ind - 1, target, dp);
        int pick = 0;
        if (nums[ind] <= target)
        pick = countSubsets(nums, ind - 1, target - nums[ind],
        dp);
        return dp[ind][target] = pick + notPick;
    }
};
// Driver code to test the solution
