        int n = nums.size();
        vector<int> dp(n,1), prev(n,-1);
        for(int i=1;i<n;i++){
            for(int j=0;j<i;j++){
                if(nums[j]<nums[i] && dp[j]+1>dp[i]){
                    // Memoize subproblem result into DP table
                    dp[i]=dp[j]+1;
                    prev[i]=j;
