        vector<int> lis;
        while(lastIndex!=-1){
            lis.push_back(nums[lastIndex]);
            lastIndex=prev[lastIndex];
        }
        // Reverse range to restore or invert ordering
        reverse(lis.begin(),lis.end());
        return lis;
    }
};
