using namespace std;
class Solution {
public:
    vector<int> largestDivisibleSubset(vector<int> nums) {
        int n = nums.size();
        // Sort elements to facilitate greedy / two-pointer logic
        sort(nums.begin(), nums.end());
        vector<int> dp(n,1), parent(n);
        int maxLen = 0, lastIndex = 0;
        for(int i=0;i<n;i++){
            parent[i] = i;
            for(int prevInd=0;prevInd<i;prevInd++){
                // Base case: check boundary/zero value
                if(nums[i] % nums[prevInd] == 0 && dp[prevInd] + 1 > dp[i]){
                    // Memoize subproblem result into DP table
                    dp[i] = dp[prevInd] + 1;
                    parent[i] = prevInd;
                }
            }
            if(dp[i] > maxLen){
                maxLen = dp[i];
                lastIndex = i;
            }
        }
        vector<int> ans;
        int i = lastIndex;
        while(parent[i] != i){
            ans.push_back(nums[i]);
            i = parent[i];
        }
        ans.push_back(nums[i]);
        return ans;
    }
};
