int countSquares(int n, int m, vector<vector<int>> &arr) {
    vector<vector<int>> dp(n, vector<int>(m, 0));
    // First row
    for(int j = 0; j < m; j++)
    // Memoize subproblem result into DP table
    dp[0][j] = arr[0][j];
    // First column
    for(int i = 0; i < n; i++)
    // Memoize subproblem result into DP table
    dp[i][0] = arr[i][0];
    // Fill DP table
    for(int i = 1; i < n; i++) {
        for(int j = 1; j < m; j++) {
            if(arr[i][j] == 0)
            // Memoize subproblem result into DP table
            dp[i][j] = 0;
            else
            // Memoize subproblem result into DP table
            dp[i][j] = 1 + min(dp[i-1][j],
            min(dp[i][j-1], dp[i-1][j-1]));
        }
    }
    // Count total squares
    int total = 0;
    for(int i = 0; i < n; i++) {
        for(int j = 0; j < m; j++) {
            total += dp[i][j];
        }
    }
    return total;
}
