    Trie trie;
    trie.insert("apple");
    trie.insert("apple");
    cout << trie.countWordsEqualTo("apple") << endl; // 2
    cout << trie.countWordsStartingWith("app") << endl; // 2
    trie.erase("apple");
    cout << trie.countWordsEqualTo("apple") << endl; // 1
    cout << trie.countWordsStartingWith("app") << endl; // 1
}
