    for (string& word : arr)
    hashSet.insert(computeHash(word));
    string result;
    for (string& word : arr) {
        if (allPrefixExist(word, hashSet)) {
            if (word.size() > result.size() ||
            (word.size() == result.size() && word < result)) {
                result = word;
            }
        }
    }
    return result;
